-- 36 Rolling Hills: rolls the wheel with the arrow keys, follows it with the
-- camera and slides the far hills and the sky for depth. The hills, the
-- island and their colliders are the engine's (`spline_shape`).
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/36-rolling-hills.scene"
local post_on = nav.post_all_on(SCENE)
local captions = true
local wheel, cam, far, sky, status
local cx, cy = -200, 0
local far_x, far_y = 0, -40

function init(entity)
    wheel = Entity.find_by_name("Wheel")
    cam = Entity.find_by_name("Camera")
    far = Entity.find_by_name("FarHills")
    sky = Entity.find_by_name("Sky")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if wheel == nil then return end
    local x, y = Transform.get_position(wheel)
    if x == nil then return end
    local dir = 0
    if Input.is_key_pressed("Right") then dir = 1 end
    if Input.is_key_pressed("Left") then dir = -1 end
    if dir ~= 0 then
        -- Spin it the way it should roll; the ground's friction does the rest.
        Physics.set_angular_velocity(wheel, -dir * 16)
    end
    if Input.is_key_just_pressed("Space") then
        local hit = Physics.raycast(x, y - 34, 0, -1, 10)
        if hit ~= nil then
            local vx, vy = Physics.get_velocity(wheel)
            Physics.set_velocity(wheel, vx or 0, 520)
        end
    end
    -- The camera follows, a little ahead of where the wheel is going.
    local vx = Physics.get_velocity(wheel) or 0
    local k = math.min(1, dt * 3)
    cx = cx + (x + vx * 0.25 - cx) * k
    cy = cy + (y + 60 - cy) * k
    if cam then Transform.set_position(cam, cx, cy) end
    if sky then Transform.set_position(sky, cx, cy) end
    if far then Transform.set_position(far, far_x + cx * 0.6, far_y + cy * 0.7) end
    if status then UI.set_text(status, "x " .. math.floor(x + 0.5)) end
end
